import{_ as e,c as a,o as i,a0 as t}from"./chunks/framework.DKRgXLPU.js";const o=JSON.parse('{"title":"Communication Under Pressure","description":"Master the art of team communication in high-pressure pétanque situations. Learn what to say, when to say it, and how to support teammates effectively.","frontmatter":{"title":"Communication Under Pressure","description":"Master the art of team communication in high-pressure pétanque situations. Learn what to say, when to say it, and how to support teammates effectively."},"headers":[],"relativePath":"en/blog/team-communication.md","filePath":"en/blog/team-communication.md"}');const n=e({name:"en/blog/team-communication.md"},[["render",function(e,o,n,r,l,s){return i(),a("div",null,[...o[0]||(o[0]=[t('<h1 id="communication-under-pressure" tabindex="-1">Communication Under Pressure <a class="header-anchor" href="#communication-under-pressure" aria-label="Permalink to &quot;Communication Under Pressure&quot;">​</a></h1><p>In pétanque, communication can make or break a team. The right words at the right moment build confidence and clarity. The wrong words — or silence when words are needed — can unravel even skilled teams.</p><h2 id="why-communication-matters" tabindex="-1">Why Communication Matters <a class="header-anchor" href="#why-communication-matters" aria-label="Permalink to &quot;Why Communication Matters&quot;">​</a></h2><p>Pétanque teams face unique communication challenges:</p><ul><li>Decisions must be made quickly</li><li>Pressure affects how we speak and listen</li><li>Non-verbal cues are visible to opponents</li><li>Individual performance affects team dynamics</li></ul><p>Effective communication creates:</p><ul><li>Shared understanding of strategy</li><li>Mutual support and confidence</li><li>Quick, clear decision-making</li><li>Resilience through difficult moments</li></ul><h2 id="the-communication-principles" tabindex="-1">The Communication Principles <a class="header-anchor" href="#the-communication-principles" aria-label="Permalink to &quot;The Communication Principles&quot;">​</a></h2><h3 id="_1-clarity-over-quantity" tabindex="-1">1. Clarity Over Quantity <a class="header-anchor" href="#_1-clarity-over-quantity" aria-label="Permalink to &quot;1. Clarity Over Quantity&quot;">​</a></h3><p>Under pressure, less is more. Clear, concise communication beats lengthy discussions:</p><p><strong>Instead of:</strong> &quot;I think maybe we should try to point here, but I&#39;m not sure, what do you think, the terrain looks tricky...&quot;</p><p><strong>Say:</strong> &quot;I&#39;ll point to the left side. The ground is better there.&quot;</p><h3 id="_2-positive-framing" tabindex="-1">2. Positive Framing <a class="header-anchor" href="#_2-positive-framing" aria-label="Permalink to &quot;2. Positive Framing&quot;">​</a></h3><p>Frame communications constructively:</p><p><strong>Instead of:</strong> &quot;Don&#39;t miss this one&quot; <strong>Say:</strong> &quot;You&#39;ve got this — trust your throw&quot;</p><p><strong>Instead of:</strong> &quot;That was terrible&quot; <strong>Say:</strong> &quot;Shake it off, next one&quot;</p><h3 id="_3-present-focus" tabindex="-1">3. Present Focus <a class="header-anchor" href="#_3-present-focus" aria-label="Permalink to &quot;3. Present Focus&quot;">​</a></h3><p>Keep communication focused on what&#39;s next, not what&#39;s past:</p><p><strong>Instead of:</strong> &quot;Why did you throw it there?&quot; <strong>Say:</strong> &quot;Okay, what&#39;s our best option now?&quot;</p><h3 id="_4-ownership-language" tabindex="-1">4. Ownership Language <a class="header-anchor" href="#_4-ownership-language" aria-label="Permalink to &quot;4. Ownership Language&quot;">​</a></h3><p>Use &quot;I&quot; statements for your own actions, &quot;we&quot; for team situations:</p><ul><li>&quot;I&#39;ll take this shot&quot;</li><li>&quot;We need to protect the point&quot;</li><li>&quot;I think we should...&quot;</li></ul><h2 id="what-to-communicate" tabindex="-1">What to Communicate <a class="header-anchor" href="#what-to-communicate" aria-label="Permalink to &quot;What to Communicate&quot;">​</a></h2><h3 id="before-each-end" tabindex="-1">Before Each End <a class="header-anchor" href="#before-each-end" aria-label="Permalink to &quot;Before Each End&quot;">​</a></h3><ul><li><strong>Strategy discussion</strong>: Brief alignment on approach</li><li><strong>Role clarity</strong>: Who&#39;s doing what</li><li><strong>Terrain observations</strong>: Relevant conditions</li></ul><h3 id="during-play" tabindex="-1">During Play <a class="header-anchor" href="#during-play" aria-label="Permalink to &quot;During Play&quot;">​</a></h3><ul><li><strong>Decisions</strong>: Clear statement of intended action</li><li><strong>Support</strong>: Encouragement before throws</li><li><strong>Information</strong>: Relevant observations about terrain or opponents</li></ul><h3 id="after-throws" tabindex="-1">After Throws <a class="header-anchor" href="#after-throws" aria-label="Permalink to &quot;After Throws&quot;">​</a></h3><ul><li><strong>Acknowledgment</strong>: Brief recognition (good or bad)</li><li><strong>Adjustment</strong>: Any strategic changes needed</li><li><strong>Reset</strong>: Help teammate refocus</li></ul><h2 id="what-not-to-communicate" tabindex="-1">What NOT to Communicate <a class="header-anchor" href="#what-not-to-communicate" aria-label="Permalink to &quot;What NOT to Communicate&quot;">​</a></h2><h3 id="avoid-during-pressure-moments" tabindex="-1">Avoid During Pressure Moments <a class="header-anchor" href="#avoid-during-pressure-moments" aria-label="Permalink to &quot;Avoid During Pressure Moments&quot;">​</a></h3><ul><li>Technical instructions (&quot;Keep your elbow in&quot;)</li><li>Criticism of past throws</li><li>Expressions of frustration</li><li>Doubt about teammate&#39;s ability</li><li>Excessive analysis</li></ul><h3 id="avoid-in-general" tabindex="-1">Avoid in General <a class="header-anchor" href="#avoid-in-general" aria-label="Permalink to &quot;Avoid in General&quot;">​</a></h3><ul><li>Blame language</li><li>Sarcasm or passive aggression</li><li>Comparisons to other players</li><li>Predictions of failure</li></ul><h2 id="non-verbal-communication" tabindex="-1">Non-Verbal Communication <a class="header-anchor" href="#non-verbal-communication" aria-label="Permalink to &quot;Non-Verbal Communication&quot;">​</a></h2><p>Your body language speaks loudly:</p><h3 id="positive-signals" tabindex="-1">Positive Signals <a class="header-anchor" href="#positive-signals" aria-label="Permalink to &quot;Positive Signals&quot;">​</a></h3><ul><li>Eye contact with teammates</li><li>Open, relaxed posture</li><li>Nodding and acknowledgment</li><li>Calm, steady movements</li></ul><h3 id="negative-signals-avoid" tabindex="-1">Negative Signals (Avoid) <a class="header-anchor" href="#negative-signals-avoid" aria-label="Permalink to &quot;Negative Signals (Avoid)&quot;">​</a></h3><ul><li>Eye rolling or sighing</li><li>Turning away from teammates</li><li>Crossed arms or closed posture</li><li>Visible frustration</li></ul><h3 id="reading-teammates" tabindex="-1">Reading Teammates <a class="header-anchor" href="#reading-teammates" aria-label="Permalink to &quot;Reading Teammates&quot;">​</a></h3><p>Learn to recognize when teammates need:</p><ul><li><strong>Space</strong>: They&#39;re processing, don&#39;t interrupt</li><li><strong>Support</strong>: They&#39;re struggling, offer encouragement</li><li><strong>Information</strong>: They&#39;re uncertain, provide clarity</li><li><strong>Energy</strong>: They&#39;re flat, bring enthusiasm</li></ul><h2 id="communication-roles" tabindex="-1">Communication Roles <a class="header-anchor" href="#communication-roles" aria-label="Permalink to &quot;Communication Roles&quot;">​</a></h2><h3 id="the-pointer" tabindex="-1">The Pointer <a class="header-anchor" href="#the-pointer" aria-label="Permalink to &quot;The Pointer&quot;">​</a></h3><ul><li>Communicate your read of the terrain</li><li>State your intended placement clearly</li><li>Ask for input when uncertain</li></ul><h3 id="the-shooter" tabindex="-1">The Shooter <a class="header-anchor" href="#the-shooter" aria-label="Permalink to &quot;The Shooter&quot;">​</a></h3><ul><li>Confirm target selection</li><li>Communicate confidence level</li><li>Request information about angles</li></ul><h3 id="the-milieu-captain" tabindex="-1">The Milieu/Captain <a class="header-anchor" href="#the-milieu-captain" aria-label="Permalink to &quot;The Milieu/Captain&quot;">​</a></h3><ul><li>Facilitate team discussions</li><li>Make final decisions when needed</li><li>Manage team energy and focus</li></ul><h2 id="pressure-situations" tabindex="-1">Pressure Situations <a class="header-anchor" href="#pressure-situations" aria-label="Permalink to &quot;Pressure Situations&quot;">​</a></h2><h3 id="when-behind" tabindex="-1">When Behind <a class="header-anchor" href="#when-behind" aria-label="Permalink to &quot;When Behind&quot;">​</a></h3><ul><li>Stay solution-focused</li><li>Maintain positive energy</li><li>Avoid blame or frustration</li><li>Celebrate small wins</li></ul><h3 id="when-ahead" tabindex="-1">When Ahead <a class="header-anchor" href="#when-ahead" aria-label="Permalink to &quot;When Ahead&quot;">​</a></h3><ul><li>Stay focused, avoid complacency</li><li>Keep communication consistent</li><li>Don&#39;t change what&#39;s working</li></ul><h3 id="match-point-theirs" tabindex="-1">Match Point (Theirs) <a class="header-anchor" href="#match-point-theirs" aria-label="Permalink to &quot;Match Point (Theirs)&quot;">​</a></h3><ul><li>Acknowledge the pressure briefly</li><li>Focus on the process</li><li>Support each other visibly</li></ul><h3 id="match-point-ours" tabindex="-1">Match Point (Ours) <a class="header-anchor" href="#match-point-ours" aria-label="Permalink to &quot;Match Point (Ours)&quot;">​</a></h3><ul><li>Stay calm and focused</li><li>Avoid premature celebration</li><li>Execute as normal</li></ul><h2 id="building-communication-skills" tabindex="-1">Building Communication Skills <a class="header-anchor" href="#building-communication-skills" aria-label="Permalink to &quot;Building Communication Skills&quot;">​</a></h2><h3 id="in-practice" tabindex="-1">In Practice <a class="header-anchor" href="#in-practice" aria-label="Permalink to &quot;In Practice&quot;">​</a></h3><ul><li>Practice communicating during training</li><li>Give and receive feedback on communication</li><li>Experiment with different approaches</li></ul><h3 id="team-agreements" tabindex="-1">Team Agreements <a class="header-anchor" href="#team-agreements" aria-label="Permalink to &quot;Team Agreements&quot;">​</a></h3><p>Establish team norms:</p><ul><li>How we handle disagreements</li><li>What support looks like</li><li>When to speak and when to stay quiet</li></ul><h3 id="post-match-review" tabindex="-1">Post-Match Review <a class="header-anchor" href="#post-match-review" aria-label="Permalink to &quot;Post-Match Review&quot;">​</a></h3><p>Discuss communication:</p><ul><li>What worked well?</li><li>What could improve?</li><li>Any misunderstandings to address?</li></ul><h2 id="when-communication-breaks-down" tabindex="-1">When Communication Breaks Down <a class="header-anchor" href="#when-communication-breaks-down" aria-label="Permalink to &quot;When Communication Breaks Down&quot;">​</a></h2><h3 id="in-the-moment" tabindex="-1">In the Moment <a class="header-anchor" href="#in-the-moment" aria-label="Permalink to &quot;In the Moment&quot;">​</a></h3><ol><li>Take a breath</li><li>Reset with a simple statement: &quot;Let&#39;s focus on this throw&quot;</li><li>Return to basics: clear, positive, present</li></ol><h3 id="after-the-match" tabindex="-1">After the Match <a class="header-anchor" href="#after-the-match" aria-label="Permalink to &quot;After the Match&quot;">​</a></h3><ul><li>Address issues calmly</li><li>Focus on behaviors, not personalities</li><li>Agree on improvements</li><li>Move forward together</li></ul><h2 id="the-silent-support" tabindex="-1">The Silent Support <a class="header-anchor" href="#the-silent-support" aria-label="Permalink to &quot;The Silent Support&quot;">​</a></h2><p>Sometimes the best communication is presence:</p><ul><li>Standing with a struggling teammate</li><li>A hand on the shoulder</li><li>A nod of confidence</li><li>Simply being there</li></ul><p>Words aren&#39;t always necessary. Connection is.</p><hr><p><em>Related: <a href="/en/education/team-player/">Team Dynamics</a> | <a href="/en/education/team-player/communication">Communication</a> | <a href="/en/education/mental-strength/handling-pressure">Handling Pressure</a></em></p>',79)])])}]]);export{o as __pageData,n as default};
